import math
Phi=lambda x: .5*math.erfc(-x/math.sqrt(2))
def gap(T,E,h,t):
 q=E/T
 return sum(math.comb(T,k)*q**k*(1-q)**(T-k)*Phi(h*(k-E-t)) for k in range(T+1))-Phi(-h*t)
for E in range(1,8):
 for T in range(E+1,E+13):
  for h in [.1,.25,.5,1,2,4,8]:
   for b in [0,.01,.1,.25,.5,1,2,4,8,16]:
    x=gap(T,E,h,b)
    if x< -1e-8:
     print("counterexample",T,E,h,b,x,"query",b+0.1,gap(T,E,h,b+.1)); raise SystemExit
print("no sample counterexample")
